(* [comment removed for export] *)
Definition sched_hdr0 (ioc : Z) : svch := mkSVC VP_SCHED 0 0 ioc 0 0.
Definition SchedCells (m : mem) (S ioc : Z) : Prop :=
  exists j50 jm j109 je jt j219,
     rw_cells rsegs m S (SvcHdrCells (sched_hdr0 ioc))
  /\ rw_cells rsegs m (S + O_SCH_ONE_THREAD) [CB 2 [b8 0; b8 0]; CB 6 j50]
  /\ rw_cells rsegs m (S + O_SCH_MUTEX) [CB 8 jm]
  /\ PMutex m (S + O_SCH_PMUTEX) 0
  /\ rw_cells rsegs m (S + O_SCH_SPIN) [C4 (wz 0); CB 1 [b8 1]; CB 3 j109]
  /\ rw_cells rsegs m (S + O_SCH_EVENT) [CB 8 je]
  /\ PCond m (S + O_SCH_COND) CLOCK_MONOTONIC
  /\ rw_cells rsegs m (S + O_SCH_EVSTATE)
       [C8 (wz 0); C8 (wz 0); C8 (wz P_SCHED_GET_DEFAULT_TASK); C8 (wz 0); C8 (wz 0); C4 (wz 0); CB 4 jt;
        CB 3 [b8 1; b8 0; b8 0]; CB 5 j219; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max); C8 (wz 0)].

(* [comment removed for export] *)
Definition cfg_elt (ioc cfgb : Z) : svce := mkSE cfgb (cfg_hdr ioc) TI_NAME_CONFIG.

Lemma cfg_chain : forall LB m cfgb ioc,
  ConfigSvc LB m cfgb (cfg_hdr ioc) -> XStatics m -> 0 < cfgb -> cfgb + NEWSZ_CFG <= 2^64 -> 0 <= ioc < 2^64 ->
  SvcChain m cfgb [cfg_elt ioc cfgb].
Proof.
  intros LB m cfgb ioc (p & j4 & j7 & IN & CH & _) XS POS HI IOCR. cbn.
  split; [reflexivity|]. split; [exact POS|]. split; [unfold NEWSZ_CFG in HI; lia|].
  split. { apply (proj1 (rw_cells_app _ _ _ (SvcHdrCells _) _)) in CH. exact (proj1 (proj1 CH)). }
  split. { unfold svch_ok, cfg_hdr, VP_CONFIG_SVC, L_TYPEID_CONFIG, P_DESTROY_ALLOC_CONFIG; cbn; lia. }
  split. { intros _. split; [exact (XS_tiname_config _ XS)|]. unfold TI_NAME_CONFIG, L_TYPEID_CONFIG; lia. }
  reflexivity.
Qed.

Lemma cfg_find : forall ioc cfgb, find_svc L_TYPEID_CONFIG 0 TI_NAME_CONFIG [cfg_elt ioc cfgb] = cfgb.
Proof. intros. cbn [find_svc cfg_elt]. rewrite (keys_match_true_ti L_TYPEID_CONFIG 0 TI_NAME_CONFIG cfgb (cfg_hdr ioc) TI_NAME_CONFIG); [reflexivity| | | reflexivity]; unfold cfg_hdr, L_TYPEID_CONFIG; cbn; lia. Qed.

(* [comment removed for export] *)
Lemma SvcChain_transport_gen : forall W m m' first L,
  SvcChain m first L -> munch W m m' ->
  Forall (fun e => disjoint_from W (se_addr e) 48 /\ (sv_ti (se_hdr e) <> 0 -> disjoint_from W (sv_ti (se_hdr e) + 8) 8)) L ->
  SvcChain m' first L.
Proof.
  intros W m m' first L. revert first. induction L as [|e L IH]; intros first CH MU OFF; [exact CH|].
  cbn in CH |- *. destruct CH as (E & POS & HI & HD & OK & TI & CH').
  pose proof (Forall_inv OFF) as [O1 O2].
  split; [exact E|]. split; [exact POS|]. split; [exact HI|].
  split. { eapply ro_cells_transport; [exact HD| exact MU|]. cbn [cells_size csize Nat.add SvcHdrCells]. exact O1. }
  split; [exact OK|]. split.
  { intros NZ. destruct (TI NZ) as (RO & R & LO' & HI'). split; [| split; [exact R| split; [exact LO'| exact HI']]].
    eapply ro_cells_transport; [exact RO| exact MU|]. cbn [cells_size csize Nat.add]. exact (O2 NZ). }
  apply IH; [exact CH'| exact MU| exact (Forall_inv_tail OFF)].
Qed.

Definition SCHED_CTOR_STACK : Z := 368 + CONFIG_GET_STACK.
Definition sc_W (lo : Z) (sp tp : word) (S regb : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (S, S + SZ_SCH); (regb + O_REG_MUTEX, regb + O_REG_MUTEX + 40); (bv_unsigned tp + -164, bv_unsigned tp + -164 + 4)]%Z.

(* [comment removed for export] *)
Definition sc_pure (S ioc regb cfgb lo : Z) (sp tp ra : word) : Prop :=
  S mod 16 = 0 /\ 0 < S /\ S + NEWSZ_SCH <= lo /\ (S + NEWSZ_SCH <= 0x10000 \/ 0xb4000 <= S)
  /\ bv_unsigned sp <= ioc /\ ioc + 24 <= 2^64
  /\ regb + NEWSZ_REG <= lo /\ (regb + SZ_REG <= 0x10000 \/ 0xb4000 <= regb)
  /\ cfgb + NEWSZ_CFG <= lo /\ 0 < cfgb /\ (cfgb + NEWSZ_CFG <= 0x10000 \/ 0xb4000 <= cfgb)
  /\ (cfgb + NEWSZ_CFG <= regb \/ regb + NEWSZ_REG <= cfgb)
  /\ (S + NEWSZ_SCH <= regb \/ regb + NEWSZ_REG <= S) /\ (S + NEWSZ_SCH <= cfgb \/ cfgb + NEWSZ_CFG <= S)
  /\ tp = Z_to_bv 64 RATP /\ bv_unsigned sp mod 16 = 0 /\ bv_unsigned sp <= 0x7fffffffffff
  /\ lo + SCHED_CTOR_STACK <= bv_unsigned sp /\ hceil <= lo /\ bv_unsigned ra mod 2 = 0.

(* [comment removed for export] *)
Definition sc_inv (LB : list block) (m : mem) (ioc regb cfgb : Z) (tp : word) (errv : word) : Prop :=
  ro_cells rsegs m (ioc + O_IOC_REGISTRY) [C8 (wz regb)]
  /\ Registry LB m regb ioc cfgb 0 /\ ConfigSvc LB m cfgb (cfg_hdr ioc)
  /\ XStatics m /\ CanaryReads m
  /\ rw_cells rsegs m (bv_unsigned tp + -164) [C4 errv].

(* [comment removed for export] *)
Definition P_SC_MID : Z := 0x2e55c.

Definition scA_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (S ioc regb cfgb lo : Z) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (jcem jev jpe jtl : list byte) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j0 jf j48,
    ms' = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -368)) gp tp t0 t1 t2 (Z_to_bv 64 S) (Z_to_bv 64 0) a0 a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 ioc) (Z_to_bv 64 0x2f854) (Z_to_bv 64 P_SCHED_GET_DEFAULT_TASK) (Z_to_bv 64 L_STR_SCHEDULER)
                  (Z_to_bv 64 (S + 56)) (Z_to_bv 64 1) (Z_to_bv 64 L_TYPEID_CONFIG) (Z_to_bv 64 1) s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_SC_MID) fc None m' (seg_rom rsegs)
    /\ munch (sc_W lo sp tp S regb) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -368)
    /\ rw_cells rsegs m' (bv_unsigned sp + -368) [CB 8 j0]
    /\ rw_cells rsegs m' (bv_unsigned sp + -360) [C8 (Z_to_bv 64 L_TYPEID_CONFIG); C8 (Z_to_bv 64 0)]
    /\ rw_cells rsegs m' (bv_unsigned sp + -344)
         [CB 256 jf; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells rsegs m' S (SvcHdrCells (sched_hdr0 ioc))
    /\ rw_cells rsegs m' (S + 48) [C1 (b8 0); C1 (b8 0); CB 6 j48]
    /\ rw_cells rsegs m' (S + 56) [CB 56 jcem] /\ rw_cells rsegs m' (S + 112) [CB 8 jev]
    /\ rw_cells rsegs m' (S + 120) [CB 56 jpe] /\ rw_cells rsegs m' (S + 176) [CB 96 jtl]
    /\ sc_inv LB m' ioc regb cfgb tp (wz 0).

Definition sched_ctorA_stmt : Prop :=
  forall (S ioc regb cfgb lo : Z) (LB : list block)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (errv : word) (jh j48 jcem jev jpe jtl : list byte),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  rw_cells rsegs m S [CB 48 jh] -> rw_cells rsegs m (S + 48) [CB 8 j48] ->
  rw_cells rsegs m (S + 56) [CB 56 jcem] -> rw_cells rsegs m (S + 112) [CB 8 jev] ->
  rw_cells rsegs m (S + 120) [CB 56 jpe] -> rw_cells rsegs m (S + 176) [CB 96 jtl] ->
  sc_pure S ioc regb cfgb lo sp tp ra -> sc_inv LB m ioc regb cfgb tp errv ->
  stk rsegs m lo (bv_unsigned sp) ->
  mem_inv rsegs m ->
  evt rsegs (scA_post sp gp tp F fc LB S ioc regb cfgb lo ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 jcem jev jpe jtl m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz S) (wz ioc) (wz 0) (wz P_SCHED_GET_DEFAULT_TASK) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SCHED_CTOR) fc None m (seg_rom rsegs)).

Lemma Registry_align : forall LB m r owner first lk, Registry LB m r owner first lk -> (r + 8) mod 4 = 0.
Proof. intros LB m r owner first lk (p & j0 & j7 & _ & _ & PM & _). exact (proj2 (proj2 PM)). Qed.

